<script setup lang="ts">
import { onMounted, reactive, ref } from 'vue'
import { ElMessage } from 'element-plus'
import { api, apiPage, mutation, uploadAttachment } from '../api/client'
import RunPanel from '../components/RunPanel.vue'
type Criterion={criterion_version_id:string;dimension:string;expected_behavior:string;pass_rule:string;unknown_rule:string;critical:boolean;allowed_methods:string[];required_artifact_types:string[]}
type Objective={objective_version_id:string;title:string;target_behavior:string;deliverables:string[];criteria:Criterion[]}
type Project={build_project_id:string;title:string;problem_statement:string}
type Task={task_id:string;title:string;description:string;build_project_id:string;objective_version_id:string;criterion_version_ids:string[];deliverables:string[];prerequisite_task_ids:string[];learning_unit_id:string|null;task_draft_id:string|null;status:string;version:number;current_task_version_id:string;current_submission_id:string|null;effective_confirmation_id:string|null;criteria:Criterion[];submissions:{submission_id:string;submission_version:number}[];versions:{task_version_id:string;version_no:number}[]}
type Unit={learning_unit_id:string;objective_version_id:string;task_drafts:{task_draft_id:string;title:string;target_behavior:string;deliverables:string[]}[]}
type Assessment={assessment_id:string;submission_id:string;version:number;criterion_version_ids:string[];items:{criterion_version_id:string;verdict:string;rationale:string;limitations:string[]}[];plan_delta_proposal_id:string;reviews:{review_id:string;self_review:boolean;criterion_decisions:{criterion_version_id:string;verdict:string;reason:string;self_review_record?:{procedure:string;observed:string;environment:string;code_version:string}}[]}[];confirmation:{revoked:boolean;decision:string}[]}
type Decision={criterion_version_id:string;verdict:'pass'|'fail'|'unknown';method:string;evidence_refs:string[];reason:string;procedure:string;observed:string;environment:string;code_version:string}
const projects=ref<Project[]>([]),projectId=ref(''),objectives=ref<Objective[]>([]),tasks=ref<Task[]>([]),task=ref<Task|null>(null),units=ref<Unit[]>([]),draftId=ref(''),runId=ref(''),assessment=ref<Assessment|null>(null),decisions=ref<Decision[]>([]),ack=ref(false),decision=ref<'accept'|'request_revision'>('request_revision'),delta=ref<{adjust:{reason:string}[]}|null>(null),busy=ref(false),revisionMode=ref(false)
const projectForm=reactive({title:'',problem_statement:'',constraints:''})
const taskForm=reactive({objective_version_id:'',title:'',description:'',deliverables:'',prerequisite_task_ids:[] as string[],change_reason:''})
const submissionForm=reactive({summary:'',code_commit:'',environment:'',command_text:'',reported_exit_code:0,explanation:'',transfer:'',actual_minutes:null as number|null})
const files=ref<File[]>([]),uploaded=ref<{attachment_id:string;name:string}[]>([]),uploadKeys=ref<string[]>([]),outputId=ref(''),revokeReason=ref('')
const write=mutation()
async function all<T>(path:string):Promise<T[]>{const rows:T[]=[];let cursor:string|null=null;do{const page:{data:T[];next_cursor?:string|null}=await apiPage<T>(path+(path.includes('?')?'&':'?')+'limit=100'+(cursor?'&cursor='+cursor:''));rows.push(...page.data);cursor=page.next_cursor??null}while(cursor);return rows}
async function load(){try{projects.value=await all('/build-projects');if(!projectId.value)projectId.value=projects.value[0]?.build_project_id??'';objectives.value=await all('/learning-objectives');units.value=await all('/learning-units');tasks.value=await all('/build-tasks')}catch(e){ElMessage.error(String(e))}}
async function createProject(){try{const result=await write<Project>('/build-projects','POST',{title:projectForm.title,problem_statement:projectForm.problem_statement,constraints:projectForm.constraints.split('\n').filter(Boolean)});projectId.value=result.build_project_id;await load();Object.assign(projectForm,{title:'',problem_statement:'',constraints:''})}catch(e){ElMessage.error(String(e))}}
function fillObjective(){const obj=objectives.value.find(o=>o.objective_version_id===taskForm.objective_version_id);if(obj){taskForm.title=obj.title;taskForm.description=obj.target_behavior;taskForm.deliverables=obj.deliverables.join('\n')}draftId.value=''}
function fillDraft(){const found=units.value.flatMap(u=>u.task_drafts.map(d=>({...d,unit:u}))).find(d=>d.task_draft_id===draftId.value);if(found){Object.assign(taskForm,{objective_version_id:found.unit.objective_version_id,title:found.title,description:found.target_behavior,deliverables:found.deliverables.join('\n')})}}
function taskBody(){const obj=objectives.value.find(o=>o.objective_version_id===taskForm.objective_version_id);const found=units.value.find(u=>u.task_drafts.some(d=>d.task_draft_id===draftId.value));return {objective_version_id:taskForm.objective_version_id,criterion_version_ids:obj?.criteria.map(c=>c.criterion_version_id)??[],title:taskForm.title,description:taskForm.description,deliverables:taskForm.deliverables.split('\n').filter(Boolean),prerequisite_task_ids:taskForm.prerequisite_task_ids,learning_unit_id:found?.learning_unit_id??null,task_draft_id:draftId.value||null}}
async function saveTask(){try{const result=revisionMode.value&&task.value?await write<Task>('/build-tasks/'+task.value.task_id+'/versions','POST',{...taskBody(),expected_version:task.value.version,change_reason:taskForm.change_reason}):await write<Task>('/build-projects/'+projectId.value+'/tasks','POST',taskBody());task.value=result;revisionMode.value=false;await load();ElMessage.success('已保存完整条件与任务内容版本。')}catch(e){ElMessage.error(String(e))}}
async function openTask(row:Task){try{task.value=await api('/build-tasks/'+row.task_id);projectId.value=row.build_project_id;assessment.value=null;delta.value=null;ack.value=false;revisionMode.value=false;if(row.current_submission_id)await readSubmission(row.current_submission_id)}catch(e){ElMessage.error(String(e))}}
function editTask(){if(!task.value)return;Object.assign(taskForm,{objective_version_id:task.value.objective_version_id,title:task.value.title,description:task.value.description,deliverables:task.value.deliverables.join('\n'),prerequisite_task_ids:[...task.value.prerequisite_task_ids],change_reason:''});draftId.value=task.value.task_draft_id??'';revisionMode.value=true}
async function transition(status:string){if(!task.value)return;try{task.value=await write('/build-tasks/'+task.value.task_id+'/transition','POST',{expected_version:task.value.version,target_status:status,reason:status==='cancelled'?'用户取消本次任务':'开始本人实践'});await load()}catch(e){ElMessage.error(String(e))}}
function chooseFiles(event:Event){files.value=Array.from((event.target as HTMLInputElement).files??[]);uploaded.value=[];uploadKeys.value=files.value.map(()=>crypto.randomUUID());outputId.value=''}
async function upload(){busy.value=true;try{for(let i=uploaded.value.length;i<files.value.length;i++){const value=await uploadAttachment(files.value[i]!,'submission',uploadKeys.value[i]);uploaded.value.push(value)}outputId.value=outputId.value||uploaded.value[0]?.attachment_id||''}catch(e){ElMessage.error(String(e))}finally{busy.value=false}}
async function submit(){if(!task.value)return;busy.value=true;try{if(uploaded.value.length<files.value.length)await upload();if(uploaded.value.length<files.value.length)return;const body={expected_version:task.value.version,task_version_id:task.value.current_task_version_id,criterion_version_ids:task.value.criterion_version_ids,summary:submissionForm.summary,code_commit:submissionForm.code_commit||null,attachment_ids:uploaded.value.map(a=>a.attachment_id),environment:submissionForm.environment?{description:submissionForm.environment}:{},execution_records:submissionForm.command_text?[{command_text:submissionForm.command_text,reported_exit_code:submissionForm.reported_exit_code,output_attachment_id:outputId.value,environment_refs:[submissionForm.environment],reported_at:new Date().toISOString(),execution_provenance:'user_reported'}]:[],explanation_answers:submissionForm.explanation?[{question:'逐项说明实现机制、限制和材料依据',answer:submissionForm.explanation,criterion_version_ids:task.value.criterion_version_ids}]:[],transfer_notes:submissionForm.transfer?[submissionForm.transfer]:[],actual_minutes:submissionForm.actual_minutes};const result=await write<{submission_id:string}>('/build-tasks/'+task.value.task_id+'/submissions','POST',body);task.value=await api('/build-tasks/'+task.value.task_id);assessment.value=null;uploaded.value=[];files.value=[];outputId.value='';await readSubmission(result.submission_id);await load();ElMessage.success('已保存不可变提交；执行来源记录为用户报告。')}catch(e){ElMessage.error(String(e))}finally{busy.value=false}}
async function readSubmission(id:string){const saved=await api<{assessment_ids:string[]}>('/submissions/'+id);const latest=saved.assessment_ids.at(-1);if(latest)await readAssessment(latest)}
async function assess(){if(!task.value?.current_submission_id)return;try{const run=await write<{run_id:string}>('/submissions/'+task.value.current_submission_id+'/assessment-runs','POST',{criterion_version_ids:task.value.criterion_version_ids,review_scope:'完整条件，材料不足保持未知'});runId.value=run.run_id}catch(e){ElMessage.error(String(e))}}
async function progress(){try{const run=await api<{output_refs:{assessment_id?:string}[]}>(`/runs/${runId.value}`);const id=run.output_refs.find(x=>x.assessment_id)?.assessment_id;if(id)await readAssessment(id)}catch(e){ElMessage.error(String(e))}}
async function readAssessment(id:string){assessment.value=await api('/assessments/'+id);decisions.value=assessment.value!.items.map(i=>({criterion_version_id:i.criterion_version_id,verdict:'unknown',method:task.value?.criteria.find(c=>c.criterion_version_id===i.criterion_version_id)?.allowed_methods.includes('human_review')?'human_review':'user_reported',evidence_refs:[],reason:'',procedure:'',observed:'',environment:'',code_version:''}));ack.value=false;decision.value='request_revision';delta.value=null}
async function confirm(){if(!assessment.value||!task.value)return;try{const chosen=decision.value;await write('/assessments/'+assessment.value.assessment_id+'/confirm','POST',{expected_version:assessment.value.version,expected_task_version:task.value.version,decision:decision.value,criterion_decisions:decisions.value.map(d=>({criterion_version_id:d.criterion_version_id,verdict:d.verdict,method:d.method,evidence_refs:d.evidence_refs,reason:d.reason,self_review_record:d.method==='human_review'?{procedure:d.procedure,observed:d.observed,environment:d.environment,code_version:d.code_version}:null})),supplementary_evidence_ids:[],scope_acknowledged:ack.value});const id=assessment.value.assessment_id;task.value=await api('/build-tasks/'+task.value.task_id);await readAssessment(id);await load();ElMessage.success(chosen==='accept'?'本次限定范围的自验已保存':'已记录返修决定，请形成新提交。')}catch(e){ElMessage.error(String(e))}}
async function revoke(){if(!assessment.value||!task.value)return;try{await write('/assessments/'+assessment.value.assessment_id+'/revoke','POST',{expected_version:assessment.value.version,expected_task_version:task.value.version,reason:revokeReason.value});const id=assessment.value.assessment_id;task.value=await api('/build-tasks/'+task.value.task_id);await readAssessment(id);await load()}catch(e){ElMessage.error(String(e))}}
async function readDelta(){if(assessment.value)try{delta.value=await api('/plan-deltas/'+assessment.value.plan_delta_proposal_id)}catch(e){ElMessage.error(String(e))}}
const statusNames:Record<string,string>={todo:'待开始',in_progress:'实践中',submitted:'已提交',needs_revision:'需返修',accepted:'已验收',cancelled:'已取消'}
onMounted(load)
</script>
<template>
<section class="page-heading"><div><span class="eyebrow">本人项目 → 提交 → 分项确认</span><h1>自主构建</h1><p>每次提交保留代码、环境和完整条件。验收结论仅覆盖本次版本与自验范围。</p></div><el-button @click="load">刷新</el-button></section>
<el-alert title="平台不执行提交命令。离线审阅仅盘点材料；程序行为与理解证据须由本人逐项核查。" :closable="false"/>
<section class="table-card panel"><h2>本人项目</h2><el-select v-model="projectId"><el-option v-for="p in projects" :key="p.build_project_id" :label="p.title" :value="p.build_project_id"/></el-select><el-collapse><el-collapse-item title="新建项目"><el-input v-model="projectForm.title" placeholder="项目名称"/><el-input v-model="projectForm.problem_statement" type="textarea" placeholder="要解决的真实问题和自己的改动"/><el-input v-model="projectForm.constraints" type="textarea" placeholder="约束，每行一项"/><el-button @click="createProject">保存本人项目</el-button></el-collapse-item></el-collapse></section>
<section class="table-card panel"><h2>{{revisionMode?'调整任务，保存新版本':'建立任务'}}</h2><el-form label-position="top"><el-form-item label="已采纳或当前手工目标"><el-select v-model="taskForm.objective_version_id" @change="fillObjective"><el-option v-for="o in objectives" :key="o.objective_version_id" :label="o.title" :value="o.objective_version_id"/></el-select></el-form-item><el-form-item label="来自学习单元的草稿（可选）"><el-select v-model="draftId" clearable @change="fillDraft"><el-option v-for="d in units.flatMap(u=>u.task_drafts)" :key="d.task_draft_id" :label="d.title" :value="d.task_draft_id"/></el-select></el-form-item><el-input v-model="taskForm.title" placeholder="任务标题"/><el-input v-model="taskForm.description" type="textarea" placeholder="实现范围与变更场景"/><el-input v-model="taskForm.deliverables" type="textarea" placeholder="交付物，每行一项"/><el-form-item label="前置任务"><el-select v-model="taskForm.prerequisite_task_ids" multiple><el-option v-for="t in tasks.filter(t=>t.build_project_id===projectId&&t.task_id!==task?.task_id)" :key="t.task_id" :label="t.title" :value="t.task_id"/></el-select></el-form-item><el-input v-if="revisionMode" v-model="taskForm.change_reason" placeholder="调整理由"/><p>将冻结所选目标的全部验收条件；修改目标范围需要先建立新目标版本。</p><el-button type="primary" :disabled="!projectId||!taskForm.objective_version_id" @click="saveTask">{{revisionMode?'保存任务新版本':'核对并创建任务'}}</el-button><el-button v-if="revisionMode" @click="revisionMode=false">取消编辑</el-button></el-form></section>
<section class="table-card panel"><h2>任务列表</h2><el-table :data="tasks.filter(t=>t.build_project_id===projectId)"><el-table-column prop="title" label="任务"/><el-table-column label="状态"><template #default="{row}">{{statusNames[row.status]}}</template></el-table-column><el-table-column label="版本"><template #default="{row}">{{row.version}}</template></el-table-column><el-table-column><template #default="{row}"><el-button link @click="openTask(row)">打开任务</el-button></template></el-table-column></el-table></section>
<section v-if="task" class="table-card panel"><h2>{{task.title}} · {{statusNames[task.status]}}</h2><p>{{task.description}}</p><small>任务修订 {{task.version}} · 内容版本 {{task.current_task_version_id.slice(0,8)}}</small><p><el-button :disabled="!['todo','needs_revision'].includes(task.status)" @click="transition('in_progress')">开始实践</el-button><el-button :disabled="!['todo','in_progress','submitted','needs_revision'].includes(task.status)" @click="editTask">调整任务内容</el-button><el-button type="danger" plain :disabled="!['todo','in_progress','submitted','needs_revision'].includes(task.status)" @click="transition('cancelled')">取消任务</el-button></p><h3>完整验收条件</h3><div v-for="c in task.criteria" :key="c.criterion_version_id"><strong>{{c.critical?'关键 · ':''}}{{c.expected_behavior}}</strong><p>通过：{{c.pass_rule}}<br>未知：{{c.unknown_rule}}<br>材料：{{c.required_artifact_types.join('、')}}</p></div><h3>提交历史</h3><el-button v-for="s in task.submissions" :key="s.submission_id" link @click="readSubmission(s.submission_id)">提交 v{{s.submission_version}}</el-button>
<el-collapse><el-collapse-item title="提交本次实现 / 返修补交"><el-form label-position="top"><el-input v-model="submissionForm.summary" type="textarea" placeholder="本次成果、失败和未知范围"/><el-input v-model="submissionForm.code_commit" placeholder="实际代码 commit（完整 40 位）"/><el-input v-model="submissionForm.environment" placeholder="实际环境与依赖版本"/><el-form-item label="独立上传本次材料（代码、日志、说明）"><input type="file" multiple accept=".py,.md,.log,.txt,.json,.xml" @change="chooseFiles"/><el-button :loading="busy" @click="upload">上传材料</el-button></el-form-item><el-input v-model="submissionForm.command_text" placeholder="本人执行的命令文本（平台不会执行）"/><el-input-number v-model="submissionForm.reported_exit_code"/><el-select v-model="outputId" placeholder="对应输出日志附件"><el-option v-for="a in uploaded" :key="a.attachment_id" :label="a.name" :value="a.attachment_id"/></el-select><el-input v-model="submissionForm.explanation" type="textarea" :rows="4" placeholder="逐项解释实现与证据对应关系"/><el-input v-model="submissionForm.transfer" type="textarea" placeholder="迁移说明：自己的修改、适用条件与局限"/><el-input-number v-model="submissionForm.actual_minutes" :min="0" placeholder="实际耗时（分钟）"/><p><el-button type="primary" :loading="busy" :disabled="['accepted','cancelled'].includes(task.status)" @click="submit">保存新提交</el-button></p></el-form></el-collapse-item></el-collapse><el-button type="primary" :disabled="!task.current_submission_id||task.status!=='submitted'" @click="assess">发起完整条件材料审阅</el-button></section>
<RunPanel v-if="runId" :key="runId" :run-id="runId" @changed="progress"/>
<section v-if="assessment&&task" class="table-card panel"><h2>审阅提案与本人决定</h2><p>离线提案不认证通过；请逐项填写实际自验过程、观察、环境与代码版本。旧提交的提案只保留为历史。</p><div v-for="d in decisions" :key="d.criterion_version_id" class="criterion"><h3>{{task.criteria.find(c=>c.criterion_version_id===d.criterion_version_id)?.expected_behavior}}</h3><p>{{assessment.items.find(i=>i.criterion_version_id===d.criterion_version_id)?.rationale}}</p><p v-for="l in assessment.items.find(i=>i.criterion_version_id===d.criterion_version_id)?.limitations" :key="l">{{l}}</p><el-select v-model="d.verdict"><el-option label="未知" value="unknown"/><el-option label="失败" value="fail"/><el-option label="通过" value="pass"/></el-select><el-select v-model="d.method"><el-option v-for="m in task.criteria.find(c=>c.criterion_version_id===d.criterion_version_id)?.allowed_methods" :key="m" :label="m==='human_review'?'本人自验':m==='user_reported'?'用户报告':'辅助审阅'" :value="m"/></el-select><el-input v-model="d.reason" type="textarea" placeholder="本项决定的证据依据与范围"/><template v-if="d.method==='human_review'"><el-input v-model="d.procedure" placeholder="本项实际自验步骤"/><el-input v-model="d.observed" placeholder="实际观察与条件的对应关系"/><el-input v-model="d.environment" placeholder="自验环境"/><el-input v-model="d.code_version" placeholder="本项自验的代码版本"/></template></div><el-radio-group v-model="decision"><el-radio value="request_revision">要求返修</el-radio><el-radio value="accept">确认本次范围验收</el-radio></el-radio-group><p><el-checkbox v-model="ack">确认只覆盖给定环境与版本；本人自验不代表独立第三方认证。</el-checkbox></p><el-button type="primary" :disabled="!ack||task.status!=='submitted'||task.current_submission_id!==assessment.submission_id" @click="confirm">保存完整分项决定</el-button><h3>已保存的分项自验记录</h3><el-collapse><el-collapse-item v-for="r in assessment.reviews" :key="r.review_id" :title="'完整分项记录 · '+(r.self_review?'当前用户本人自验':'用户提供')"><div v-for="d in r.criterion_decisions" :key="d.criterion_version_id"><strong>{{task.criteria.find(c=>c.criterion_version_id===d.criterion_version_id)?.expected_behavior}} · {{d.verdict==='pass'?'通过':d.verdict==='fail'?'失败':'未知'}}</strong><p>{{d.reason}}</p><p v-if="d.self_review_record">步骤：{{d.self_review_record.procedure}}<br>观察：{{d.self_review_record.observed}}<br>环境：{{d.self_review_record.environment}}<br>版本：{{d.self_review_record.code_version}}</p></div></el-collapse-item></el-collapse><h3>确认记录</h3><p v-for="(c,n) in assessment.confirmation" :key="n">{{c.decision==='accept'?'验收':'返修'}} · {{c.revoked?'已撤销':'已记录'}}</p><el-input v-model="revokeReason" placeholder="撤销当前有效确认的原因"/><el-button :disabled="!task.effective_confirmation_id" @click="revoke">撤销当前确认</el-button><p><el-button @click="readDelta">查看计划差异建议</el-button></p><p v-for="(a,n) in delta?.adjust" :key="n">{{a.reason}}</p><p v-if="delta">建议不会修改已有任务或自动采纳计划。<router-link to="/planning">返回计划核对</router-link></p></section>
</template>
<style scoped>.panel{padding:24px;margin:20px 0}.panel .el-input,.panel .el-textarea{margin:8px 0}.panel .el-select{min-width:220px;margin:8px 8px 8px 0}.criterion{border-top:1px solid #ddd;margin:20px 0;padding:10px 0}</style>
